DRY_RUN = True

print(f"Corrector: {selima.email} (id={selima.id})")
print(f"Mode: {'DRY RUN' if DRY_RUN else 'LIVE IMPORT'}")
created = updated = skipped = errors = 0
for old_uuid, sd in RECOVERED.items():
    anon = OLD_TO_ANON.get(old_uuid)
    if not anon:
        print(f"ERROR: no mapping for {old_uuid}"); errors += 1; continue
    copy = Copy.objects.filter(anonymous_id=anon).first()
    if not copy:
        print(f"ERROR: no copy for {anon}"); errors += 1; continue
    total = round(sum(v for v in sd.values() if isinstance(v,(int,float))),2)
    existing = Score.objects.filter(copy=copy).first()
    if existing:
        if existing.scores_data:
            old_t = round(sum(v for v in existing.scores_data.values() if isinstance(v,(int,float))),2)
        else:
            old_t = 0
        if abs(total - old_t) < 0.01:
            print(f"  {anon}: SKIP (={old_t})"); skipped += 1
        else:
            print(f"  {anon}: UPDATE {old_t}->{total}")
            if not DRY_RUN: existing.scores_data = sd; existing.save()
            updated += 1
    else:
        print(f"  {anon}: CREATE total={total}")
        if not DRY_RUN: Score.objects.create(copy=copy, scores_data=sd, final_comment="")
        created += 1
print(f"\nCreated:{created} Updated:{updated} Skipped:{skipped} Errors:{errors} Total:{created+updated+skipped+errors}/27")
if DRY_RUN: print("DRY RUN - set DRY_RUN=False to import")
